   /**
    * Creates the provided command.
    * 
    * @param		command ${class.getCreateCommandAlias()}
    * @exception    ProcessingException
    * @exception	IllegalArgumentException
    * @return		InferenceEndpoint
    */
	public InferenceEndpoint createInferenceEndpoint( CreateInferenceEndpointCommand command )
    throws ProcessingException, IllegalArgumentException {

		InferenceEndpoint entity = new InferenceEndpoint();

		try {
			// --------------------------------------
        	// validate the command
        	// --------------------------------------    	
        	InferenceEndpointValidator.getInstance().validate( command );    

            entity.setInferenceEndpointId( command.getInferenceEndpointId() );
            entity.setName( command.getName() );
            entity.setEndpointUrl( command.getEndpointUrl() );
            entity.setTrafficShare( command.getTrafficShare() );
            entity.setMode( command.getMode() );
    	    
        	// ------------------------------------------
        	// persist a new one
        	// ------------------------------------------ 
    	    entity = projector.create(entity);
    	    
			LOGGER.log( Level.INFO, "done creating of InferenceEndpoint {0} ", entity.toString() );
			
        }
        catch (Exception exc) {
            final String errMsg = "Unable to create InferenceEndpoint - " + exc;
            LOGGER.log( Level.WARNING, errMsg, exc );
            throw new ProcessingException( errMsg, exc );
        }
        finally {
        }        
        
        return entity;
    }

