    /**
     * assign ModelVersion on InferenceEndpoint
     * @param		command AssignModelVersionToInferenceEndpointCommand	
     * @exception	ProcessingException
     */     
	public void assignModelVersion( AssignModelVersionToInferenceEndpointCommand command ) throws ProcessingException {

		try {
			// --------------------------------------
	    	// best to validate the command now
	    	// --------------------------------------    
	    	InferenceEndpointValidator.getInstance().validate( command );    

			// --------------------------------------
	    	// delegate to the projector
	    	// --------------------------------------    	    	
	    	projector.assignModelVersion(command.getInferenceEndpointId(), command.getAssignment());
		    
		}
        catch( Throwable exc ) {
			final String msg = "Failed to get ModelVersion using id " + command.getInferenceEndpointId();
			LOGGER.log( Level.WARNING,  msg );
			throw new ProcessingException( msg, exc );
        }
	}

